function Loans(){const [principal,setPrincipal]=useState("250000");const [rate,setRate]=useState("11");const [months,setMonths]=useState("24");const p=Number(principal)||0,r=(Number(rate)||0)/1200,n=Number(months)||1;const emi=r===0?p/n:p*r*Math.pow(1+r,n)/(Math.pow(1+r,n)-1);return <div className="page-content"><SectionTitle eyebrow="BORROW WITH CLARITY" title="Loan simulator" subtitle="Explore a sample EMI calculation. No loan application is submitted."/><div className="loan-sim-grid"><div className="panel transfer-form"><h3>Personal loan calculator</h3><label>Loan amount (₹)<input value={principal} onChange={e=>setPrincipal(e.target.value.replace(/\D/g,""))}/></label><label>Annual interest rate (%)<input value={rate} onChange={e=>setRate(e.target.value)}/></label><label>Tenure (months)<input value={months} onChange={e=>setMonths(e.target.value.replace(/\D/g,""))}/></label></div><div className="panel emi-result"><span className="eyebrow">ESTIMATED MONTHLY EMI</span><strong>{money(Math.round(emi*100))}</strong><p>Principal: {money(p*100)}</p><p>Estimated total repayment: {money(Math.round(emi*n*100))}</p><span className="demo-note">Illustrative calculation only.</span></div></div></div>}
