function SettingsPage({dark,setDark,reset}:{dark:boolean;setDark:(v:boolean)=>void;reset:()=>void}){const [section,setSection]=useState("Profile information");return <div className="page-content"><SectionTitle eyebrow="YOUR EXPERIENCE" title="Settings" subtitle="Manage your profile, appearance and demo data."/><div className="settings-layout"><div className="settings-nav panel">{["Profile information","Security & login","Notifications","Appearance","Privacy & data"].map(s=><button className={section===s?"selected":""} key={s} onClick={()=>setSection(s)}>{s}<ChevronRight size={15}/></button>)}</div><div className="panel settings-panel"><h3>{section}</h3>{section==="Profile information"?<><div className="profile-edit"><div className="profile-avatar">TG</div><div><b>Tushar Gupta</b><p className="muted">NEXORA demo customer</p></div></div><div className="form-row"><label>Full name<input defaultValue="Tushar Gupta"/></label><label>Email address<input defaultValue="tushar@nexora.demo"/></label></div><div className="form-row"><label>Phone number<input defaultValue="+91 98••• ••210"/></label><label>Customer ID<input defaultValue="NX-DEMO-2048" disabled/></label></div><span className="demo-note">Profile edits are visual demo preferences only.</span></>:section==="Appearance"?<div className="setting-option"><div><b>Color theme</b><span>Switch between NEXORA dark and light modes.</span></div><button className={`toggle ${!dark?"on":""}`} onClick={()=>setDark(!dark)}><i/></button></div>:section==="Security & login"?<div className="setting-option"><div><b>Demo security centre</b><span>Authentication and device controls are not connected to a server in this frontend-only build.</span></div><ShieldCheck/></div>:section==="Notifications"?<div className="setting-option"><div><b>Banking notifications</b><span>Generated locally by simulated account activity.</span></div><Bell/></div>:<div className="setting-option"><div><b>Local demo data</b><span>Balances and transactions are stored in this browser only.</span></div><button className="danger-btn" onClick={reset}><RotateCcw size={14}/> Reset demo</button></div>}</div></div></div>}
function TransferDialog({bank,onClose,onComplete}:{bank:ReturnType<typeof useDemoBank>;onClose:()=>void;onComplete:(args:{fromId:string;beneficiaryId:string;amountPaise:number;note:string;outcome:"COMPLETED"|"PENDING"|"FAILED"})=>BankTransaction|null}){
 const [fromId,setFromId]=useState(bank.accounts[0].id);const [to,setTo]=useState(bank.beneficiaries[0]?.id||"");const [amount,setAmount]=useState("");const [note,setNote]=useState("");const [outcome,setOutcome]=useState<"COMPLETED"|"PENDING"|"FAILED">("COMPLETED");const [step,setStep]=useState<"form"|"review"|"error">("form");const [error,setError]=useState("");
 const cents=Math.round(Number(amount)*100);const beneficiary=bank.beneficiaries.find(b=>b.id===to);const from=bank.accounts.find(a=>a.id===fromId)!;
 const submit=()=>{if(!beneficiary){setError("Select a beneficiary.");return}if(!Number.isFinite(cents)||cents<=0){setError("Enter an amount greater than zero.");return}if(cents>from.balancePaise){setError("Insufficient demo account balance.");return}setStep("review");setError("")};
 const confirm=()=>{const tx=onComplete({fromId,beneficiaryId:to,amountPaise:cents,note,outcome});if(tx)onClose();else{setError("We couldn't complete this simulated transfer.");setStep("error")}};
 return <Dialog title={step==="form"?"New transfer":step==="review"?"Review transfer":"Transfer not completed"} subtitle="Simulated money movement · no real funds are involved." onClose={onClose}>
 {step==="form"?<div className="workflow-form"><label>From account<HaloSelect value={fromId} onValueChange={setFromId} options={bank.accounts.map(a=>({value:a.id,label:`${a.type} ···· ${a.number.slice(-4)} — ${money(a.balancePaise)}`}))}/></label><label>Beneficiary<HaloSelect value={to} onValueChange={setTo} placeholder="Choose recipient" options={bank.beneficiaries.map(b=>({value:b.id,label:`${b.name} ···· ${b.accountLast4} (${b.kind})`}))}/></label><label>Amount (₹)<input inputMode="decimal" placeholder="0.00" value={amount} onChange={e=>setAmount(e.target.value.replace(/[^\d.]/g,""))}/></label><label>Simulation outcome<HaloSelect value={outcome} onValueChange={v=>setOutcome(v as "COMPLETED"|"PENDING"|"FAILED")} options={[{value:"COMPLETED",label:"Complete successfully",description:"Post the simulated transaction"},{value:"PENDING",label:"Mark as pending",description:"Keep it awaiting processing"},{value:"FAILED",label:"Simulate failure",description:"Record an unsuccessful attempt"}]}/></label><label>Note (optional)<input placeholder="What's this transfer for?" value={note} onChange={e=>setNote(e.target.value)}/></label>{error&&<div className="inline-error"><AlertCircle size={14}/>{error}</div>}<div className="secure-note"><ShieldCheck size={15}/> Demo transfer validation is applied locally.</div><PrimaryButton onClick={submit}>Review transfer <ArrowRight size={15}/></PrimaryButton></div>:<div className="review-box"><div className="review-amount">{money(cents)}</div><div className="review-line"><span>From</span><b>{from.type} ···· {from.number.slice(-4)}</b></div><div className="review-line"><span>To</span><b>{beneficiary?.name}</b></div><div className="review-line"><span>Recipient type</span><b>{beneficiary?.kind==="INTERNAL"?"NEXORA internal":"Simulated external"}</b></div><div className="review-line"><span>Note</span><b>{note||"—"}</b></div>{error&&<div className="inline-error">{error}</div>}<div className="modal-actions"><GhostButton onClick={()=>setStep("form")}>Back</GhostButton><PrimaryButton onClick={confirm}>Confirm transfer <Check size={15}/></PrimaryButton></div></div>}
 </Dialog>
}
function PaymentDialog({bank,onClose,onComplete}:{bank:ReturnType<typeof useDemoBank>;onClose:()=>void;onComplete:(args:{fromId:string;merchant:string;amountPaise:number;note:string;outcome:"COMPLETED"|"PENDING"|"FAILED"})=>BankTransaction|null}){
 const [fromId,setFromId]=useState(bank.accounts[0].id);const [merchant,setMerchant]=useState("");const [amount,setAmount]=useState("");const [note,setNote]=useState("");const [outcome,setOutcome]=useState<"COMPLETED"|"PENDING"|"FAILED">("COMPLETED");const [review,setReview]=useState(false);const [error,setError]=useState("");const cents=Math.round(Number(amount)*100);const from=bank.accounts.find(a=>a.id===fromId)!;
 const confirm=()=>{if(!merchant.trim()||!cents||cents<1){setError("Enter a merchant and a valid amount.");return}if(cents>from.balancePaise){setError("Insufficient demo account balance.");return}const tx=onComplete({fromId,merchant,amountPaise:cents,note,outcome});if(tx)onClose();else setError("Payment could not be completed.")};
 return <Dialog title={review?"Review payment":"New payment"} subtitle="Simulated merchant payment · no real charge will be made." onClose={onClose}>{!review?<div className="workflow-form"><label>Pay from<HaloSelect value={fromId} onValueChange={setFromId} options={bank.accounts.map(a=>({value:a.id,label:`${a.type} ···· ${a.number.slice(-4)} — ${money(a.balancePaise)}`}))}/></label><label>Merchant / biller<input value={merchant} onChange={e=>setMerchant(e.target.value)} placeholder="e.g. Netflix, electricity bill"/></label><label>Amount (₹)<input inputMode="decimal" value={amount} onChange={e=>setAmount(e.target.value.replace(/[^\d.]/g,""))} placeholder="0.00"/></label><label>Simulation outcome<HaloSelect value={outcome} onValueChange={v=>setOutcome(v as "COMPLETED"|"PENDING"|"FAILED")} options={[{value:"COMPLETED",label:"Complete successfully",description:"Post the simulated transaction"},{value:"PENDING",label:"Mark as pending",description:"Keep it awaiting processing"},{value:"FAILED",label:"Simulate failure",description:"Record an unsuccessful attempt"}]}/></label><label>Note (optional)<input value={note} onChange={e=>setNote(e.target.value)} placeholder="Payment note"/></label>{error&&<div className="inline-error">{error}</div>}<PrimaryButton onClick={()=>{if(!merchant.trim()||!cents||cents<1){setError("Enter a merchant and a valid amount.");return}if(cents>from.balancePaise){setError("Insufficient demo account balance.");return}setError("");setReview(true)}}>Review payment <ArrowRight size={15}/></PrimaryButton></div>:<div className="review-box"><div className="review-amount">{money(cents)}</div><div className="review-line"><span>Merchant</span><b>{merchant}</b></div><div className="review-line"><span>Pay from</span><b>{from.type} ···· {from.number.slice(-4)}</b></div><div className="review-line"><span>Note</span><b>{note||"—"}</b></div>{error&&<div className="inline-error">{error}</div>}<div className="modal-actions"><GhostButton onClick={()=>setReview(false)}>Back</GhostButton><PrimaryButton onClick={confirm}>Confirm payment <Check size={15}/></PrimaryButton></div></div>}</Dialog>
}
