 const [name,setName]=useState("");const [last4,setLast4]=useState("");const [kind,setKind]=useState<"INTERNAL"|"EXTERNAL">("EXTERNAL");const [bankName,setBankName]=useState("Demo National Bank");const [targetAccountId,setTargetAccountId]=useState(bank.accounts[1]?.id||"");const [error,setError]=useState("");
