function TransactionDetail({tx,onClose,onPrint}:{tx:BankTransaction;onClose:()=>void;onPrint:(tx:BankTransaction)=>void}){return <Dialog title="Transaction details" subtitle={`Reference ${tx.reference}`} onClose={onClose}><div className="detail-hero"><div className={`detail-status ${tx.status.toLowerCase()}`}>{tx.status==="COMPLETED"?<CheckCircleIcon/>:<Clock3 size={18}/>} {tx.status}</div><strong className={tx.direction==="in"?"positive":"negative"}>{tx.direction==="in"?"+":"−"}{money(tx.amountPaise)}</strong><span>{tx.counterparty}</span></div><div className="review-line"><span>Transaction type</span><b>{tx.type}</b></div><div className="review-line"><span>From account</span><b>{tx.fromAccountLabel}</b></div><div className="review-line"><span>Date</span><b>{dateLabel(tx.createdAt)}</b></div><div className="review-line"><span>Reference</span><b>{tx.reference}</b></div><div className="review-line"><span>Description</span><b>{tx.description||"—"}</b></div><div className="modal-actions"><GhostButton onClick={()=>navigator.clipboard?.writeText(tx.reference)}><Copy size={14}/> Copy reference</GhostButton>{tx.status==="COMPLETED"&&<PrimaryButton onClick={()=>onPrint(tx)}><Printer size={14}/> View receipt printer</PrimaryButton>}</div></Dialog>}
